async function loadWorkspace(){S.workspaceEpoch.bump();S.workspaceStatus.set('loading');const alive=S.workspaceEpoch.guard();try{return await workspaceLoader.load()}catch(error){if(alive()&&!error?.committed)S.workspaceStatus.set('error');throw error}}
async function start(){try{const sharedId=location.pathname.startsWith('/s/')?location.pathname.slice(3):null;if(sharedId){S.batch(()=>{S.shared.set(true);S.shareId.set(sharedId)});const document=await api('shared?id='+encodeURIComponent(sharedId));S.batch(()=>{S.documentStore.replace(document);S.people.set(ws().people);S.boardId.set(ws().boards[0]?.id)});renderBoard();return}const config=await api('status');S.batch(()=>{S.config.set(config);S.user.set(config.user)});if(!config.ready)return setup();if(new URLSearchParams(location.search).has('verify'))return verifyScreen();if(!S.user.get()){resetPrivateState();return login();}S.boardId.set(new URLSearchParams(location.search).get('board')||S.boardId.get());await loadWorkspace();const focus=new URLSearchParams(location.search).get('item');if(focus)focusItem(S.boardId.get(),focus)}catch(e){setup(e.message)}}
function setup(error=''){const c=S.config.get();app.innerHTML=`<section class="gate">${artSVG('sprout')}<p class="eyebrow">Before the first page</p><h1>Connect your notebook.</h1><p>Boards opens directly in your cloud workspace. Until the connection and sign-in are ready, this page stays closed.</p><ul class="setup-checks">${(c?.checks||[]).map(x=>`<li class="setup-check"><span class="${x.ready?'ready':''}">${x.ready?'✓':'○'}</span><div>${esc(x.label)}<small>${esc(x.message||x.keys.join(' / '))}</small></div></li>`).join('')}</ul>${error?`<p class="form-error">${esc(error)}</p>`:''}<p class="small">Run setup on the server or your own computer. Credentials never go into the browser or public source code.</p><pre>npm run setup\n# Then restart, or run npm run deploy</pre><div class="actions"><button class="primary" id="recheck">Check connection again</button></div></section>`;$('#recheck').onclick=()=>start()}
function login(error=''){app.innerHTML=`<section class="gate">${artSVG('book')}<p class="eyebrow">Your pages are waiting</p><h1>Come on in.</h1><p>Sign in with a connected account. This notebook is for invited people only.</p><div class="login-options">${S.config.get().providers.map(p=>`<button class="button" data-login="${p}">Continue with ${esc(p[0].toUpperCase()+p.slice(1))}</button>`).join('')}${S.config.get().test?'<button class="primary" id="test-login">Open local test workspace</button><p class="small muted">Explicit test mode. No cloud connection or real identity is being simulated.</p>':''}</div>${S.config.get().email?'<form id="email-login" class="separated"><label>Email address<input name="email" type="email" autocomplete="email" required></label><button class="primary">Send sign-in link</button></form>':''}<p class="form-error">${esc(error)}</p><p class="small muted">Link additional accounts from your profile after signing in. Matching email addresses never silently combine provider accounts.</p></section>`;$$('[data-login]').forEach(b=>b.onclick=()=>oauth(b.dataset.login));$('#test-login')?.addEventListener('click',async()=>{try{await post('auth/test',{});await start()}catch(e){toast(e.message)}});$('#email-login')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await post('auth/email',{email:new FormData(e.target).get('email')});toast('A sign-in link was sent if this email is invited.')}catch(e){toast(e.message)}finally{b.disabled=false}})}
function verifyScreen(){app.innerHTML=`<section class="gate"><p class="eyebrow">Just one last step</p><h1>Open your notebook?</h1><p>Confirm to use this one-time email sign-in link.</p><button class="primary" id="verify">Sign in</button></section>`;$('#verify').onclick=async()=>{try{await post('auth/verify',{token:new URLSearchParams(location.search).get('verify')});history.replaceState({},'','/');await start()}catch(e){toast(e.message)}}}
async function oauth(provider,link=false,proposalId=null){try{if(ws())await flush();const r=await post('auth/start',{provider,link,proposalId});location.assign(r.url)}catch(e){toast(e.message)}}
/** Sign-out/login gate: one reset disposes sync, popover, hover card, observer, editor and cancels pending tasks. */
function resetPrivateState(){workspaceLoader.clear();S.resetPrivate()}
function linkedText(t){let at=0,out='';for(const r of references(t,board()?.githubRepo)){out+=esc(t.slice(at,r.start));out+=`<a href="${esc(r.url||'#')}" data-ticket="${esc(t.slice(r.start,r.end))}" rel="noopener noreferrer"${r.url?' target="_blank"':''}>${esc(r.label)}</a>`;at=r.end}return out+esc(t.slice(at))}
function taskHTML(t,c){const orphan=unresolvedHints(t,S.people.get()),avatars=(t.assignees||[]).map(id=>{const p=S.people.get().find(p=>p.id===id);return p?`<button class="avatar-button" data-person="${esc(id)}" aria-label="${esc(p.name)}"><img class="avatar${p.avatarPending?' pending':''}" src="${esc(p.avatar||'/placeholder.svg')}" alt="${esc(p.name)}" loading="lazy" referrerpolicy="no-referrer"></button>`:''}).join('');return `<li class="task${t.id==='l4'?' group-start':''}${t.done?' done':''}${S.selected.has(t.id)?' selected':''}${ws().neighborIds?.includes(t.id)?' neighbor':''}" id="item-${esc(t.id)}" data-item="${esc(t.id)}" data-col="${esc(c.id)}"><button class="task-check" data-done aria-label="${t.done?'Reopen':'Complete'} ${esc(t.text)}" aria-pressed="${t.done}"${shared()?' disabled':''}><span class="ring"></span></button><div class="task-text" data-edit="item" tabindex="${shared()?'-1':'0'}" role="${shared()?'text':'textbox'}" aria-label="Task text" aria-multiline="true">${linkedText(t.text)}</div><div class="task-actions">${avatars}${orphan.map(h=>`<button class="avatar-button unresolved" data-assign data-resolve-hint="${esc(h)}" aria-label="Resolve assignee ${esc(h)}"><img class="avatar" src="/placeholder.svg" alt="Unresolved ${esc(h)}" title="Unresolved: ${esc(h)}"></button>`).join('')}${!shared()?'<button class="add-person" data-assign aria-label="Assign a person"></button>':''}</div>${!shared()?'<button class="task-more" data-item-menu aria-label="Task actions">⋮</button>':''}</li>`}
function renderBoard(){if(editEl())finishEdit();closePop();clearHover();if(!ws()?.boards?.length)return;const b=board();document.title=b.title;app.innerHTML=`<article class="paper" style="--cols:${Math.max(1,b.columns.length)};--heading-weight:${b.typography.headingWeight};--body-weight:${Math.max(520,b.typography.bodyWeight)};--width:${b.typography.width}"><div class="paper-caption"><span class="board-title" data-edit="title" tabindex="${shared()?'-1':'0'}">${esc(b.title)}</span><span class="tagline" data-edit="tagline">${esc(b.tagline)}</span></div><nav class="column-tabs" aria-label="Columns on this page">${b.columns.map(c=>`<button data-column-jump="${esc(c.id)}" aria-current="${c.id===(S.columnId.get()||b.columns[0]?.id)?'true':'false'}">${esc(c.title)}</button>`).join('')}</nav><div class="columns">${b.columns.map((c,i)=>`<section class="column" data-col="${esc(c.id)}" id="column-${esc(c.id)}"><div class="hero">${c.illustrationId?.startsWith('art-')?`<img class="generated-art" src="${shared()?'/api/share-image?id='+esc(S.shareId.get())+'&art=':'/api/illustration?id='}${esc(c.illustrationId)}" alt="Drawing for ${esc(c.title)}">`:artSVG(c.illustrationId||pickArt(c.title))}<div class="scribble" data-edit="note" tabindex="${shared()?'-1':'0'}">${esc(c.note)}</div>${!shared()?'<button class="redraw" data-redraw>New sketch ↗</button>':''}</div><h1 data-edit="column-title" tabindex="${shared()?'-1':'0'}">${esc(c.title)}</h1>${!shared()?'<button class="column-menu" data-column-menu aria-label="Column actions">'+icon('more')+'</button>':''}<div class="column-subtitle" data-edit="subtitle" tabindex="${shared()?'-1':'0'}">${esc(c.subtitle)}</div><ul class="tasks">${c.items.map(t=>taskHTML(t,c)).join('')}</ul>${!c.items.length?'<div class="empty-column">A little room for<br>your next big idea.</div>':''}${!shared()?'<button class="add-item" data-add-item>+ Add a thought</button>':''}<div class="end-note">${i===0?'A cleaner, faster,\nmore delightful experience.':i===1?'Better tools\ncreate happier users.':'Great products\ndeserve great stories.'}</div>${i===2?artSVG('flag',{className:'end-doodle'}):''}</section>`).join('')}${!b.columns.length?'<section class="empty-column">A fresh page. Add your first column from the page tabs.</section>':''}</div><div class="paper-footer"><span data-edit="footer">${esc(b.footer)}</span><span class="after">A brighter internet ahead.</span></div></article><nav class="edge-tabs" aria-label="Notebook navigation"><button class="edge-tab" data-nav="boards" aria-label="Boards and columns">${icon('boards')}<span>Pages</span></button>${!shared()?`<button class="edge-tab" data-nav="search" aria-label="Search workspace">${icon('search')}<span>Find</span></button><button class="edge-tab" data-nav="share" aria-label="Share selection or board">${icon('share')}<span>Share</span></button><button class="edge-tab" data-nav="more" aria-label="Notebook settings and profile">${icon('more')}<span>More</span>${S.requests.get().some(p=>p.target===S.user.get()?.id)?'<i class="dot"></i>':''}</button>`:''}</nav><div class="save-state" role="status">${saveLabel(S.saveStatus.get())}</div>`;bindBoard();observeColumns();}
function bindBoard(){app.onclick=async e=>{const target=e.target.closest('button,a,[data-edit]');if(!target)return;const row=target.closest('[data-item]'),col=target.closest('[data-col]')?.dataset.col;S.columnId.set(col||S.columnId.get());
 if(target.hasAttribute('data-column-jump')){finishEdit();S.columnId.set(target.dataset.columnJump);$('#column-'+CSS.escape(S.columnId.get()))?.scrollIntoView({behavior:'smooth',block:'start'});return}
 if(target.dataset.nav){finishEdit();return ({boards:pages,search:searchDialog,share:shareDialog,more:moreDialog})[target.dataset.nav]()}
 if(target.hasAttribute('data-person'))return profile(target.dataset.person);
 if(target.hasAttribute('data-ticket')){e.preventDefault();return ticketDialog(target.dataset.ticket,row)}
 if(shared())return;
 if(target.hasAttribute('data-edit'))return startEdit(target);
 if(target.hasAttribute('data-done'))return change(cmd('toggleDone',ref(col,row.dataset.item)));
 if(target.hasAttribute('data-assign'))return peoplePicker(row,target);
 if(target.hasAttribute('data-item-menu'))return itemMenu(row,target);
 if(target.hasAttribute('data-column-menu'))return columnMenu(col,target);
 if(target.hasAttribute('data-add-item'))return addItem(col);
 if(target.hasAttribute('data-redraw'))return redraw(col,true);
 };app.onkeydown=e=>{if(e.target.matches('[data-edit]')&&!e.target.isContentEditable&&(e.key==='Enter'||e.key===' ')){e.preventDefault();startEdit(e.target)}};app.onmouseover=e=>{const p=e.target.closest('[data-person]'),t=e.target.closest('[data-ticket]');if(p)profileHover(p);else if(t)ticketHover(t)};app.onmouseout=e=>{if(e.target.closest('[data-person],[data-ticket]'))clearHover()};$$('img.avatar',app).forEach(im=>im.onerror=()=>{im.onerror=null;im.src='/placeholder.svg'});}
function observeColumns(){S.columnObserver.clear();if(!('IntersectionObserver' in window))return;const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;S.columnId.set(visible.target.dataset.col);$$('[data-column-jump]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.columnJump===S.columnId.get())))},{rootMargin:'-12% 0px -60% 0px',threshold:[0,.1,.5]});S.columnObserver.set(observer,o=>o.disconnect());$$('.column',app).forEach(c=>observer.observe(c))}
/** Describes what an editable element writes to: a JSON-safe reference plus the key and its length limit. */
function fieldRef(el){const columnId=el.closest('[data-col]')?.dataset.col,itemId=el.closest('[data-item]')?.dataset.item,boardId=board().id;switch(el.dataset.edit){case'item':return{ref:{target:'item',boardId,columnId,itemId},key:'text',max:1000};case'column-title':return{ref:{target:'column',boardId,columnId},key:'title',max:120};case'note':return{ref:{target:'column',boardId,columnId},key:'note',max:240};case'subtitle':return{ref:{target:'column',boardId,columnId},key:'subtitle',max:180};default:return{ref:{target:'board',boardId},key:el.dataset.edit,max:el.dataset.edit==='title'?120:240}}}
function nodeOf({target,boardId,columnId,itemId}){const b=ws().boards.find(x=>x.id===boardId)||ws().boards[0];if(target==='board')return b;const c=b.columns.find(x=>x.id===columnId);return target==='column'?c:c.items.find(t=>t.id===itemId)}
const releaseEditor=el=>{el.contentEditable='false';el.oninput=null;el.onkeydown=null;el.onblur=null};
function startEdit(el){if(shared()||syncQ()?.paused||editEl()===el)return;finishEdit();const{ref,key,max}=fieldRef(el),obj=nodeOf(ref);S.batch(()=>{S.editor.set(el,releaseEditor);S.editMeta.set({ref,key,max,old:obj[key]})});el.textContent=obj[key];el.contentEditable='plaintext-only';el.focus();const range=document.createRange();range.selectNodeContents(el);range.collapse(false);const sel=getSelection();sel.removeAllRanges();sel.addRange(range);el.oninput=()=>{if(el.textContent.length>max)toast(`Please keep this to ${max} characters.`);if(key==='text')suggest(el)};el.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();el.textContent=S.editMeta.peek().old;finishEdit();renderBoard()}else if(e.key==='Enter'&&!e.shiftKey&&!popEl()?.classList.contains('mentions')){e.preventDefault();finishEdit();renderBoard()}};el.onblur=()=>setTimeout(()=>{if(editEl()===el&&!popEl()?.contains(document.activeElement)){finishEdit();renderBoard()}},170);}
function finishEdit(){const el=editEl();if(!el)return;const{ref,key,max,old}=S.editMeta.peek();S.batch(()=>{S.editor.take();S.editMeta.set(null)});releaseEditor(el);suggestTask.cancel();const text=el.innerText.replace(/\r/g,'').trim().slice(0,max);el.textContent=text;if(text!==old){const retitled=ref.target==='column'&&key==='title';change(cmd('setField',{...ref,key,value:text,clearIllustration:retitled}),{render:false,allowPaused:true});if(retitled)setTimeout(()=>redraw(ref.columnId,false),650)}closePop();}
function addItem(col){const id=uid();change(()=>board().columns.find(c=>c.id===col).items.push({id,text:'',tag:'',assignees:[],done:false}));startEdit($(`#item-${CSS.escape(id)} [data-edit]`));}
const disposePopover=el=>{if(el.restoreKeys)el.restoreKeys();el.remove()};
function closePop(){S.popover.clear()}
function popup(anchor,html,{mentions=false}={}){closePop();const pop=document.createElement('div');pop.className='popover'+(mentions?' mentions':'');pop.setAttribute('role','listbox');pop.innerHTML=html;document.body.append(pop);const r=anchor.getBoundingClientRect(),w=pop.getBoundingClientRect().width;pop.style.left=Math.max(12,Math.min(innerWidth-w-12,r.left))+'px';pop.style.top=Math.max(12,Math.min(innerHeight-pop.offsetHeight-100,r.bottom+8))+'px';pop.onmousedown=e=>{if(e.target.closest('button'))e.preventDefault()};S.popover.set(pop,disposePopover);return pop}
function peoplePicker(row,anchor,query='',fromMention=false){const resolveHint=anchor.dataset.resolveHint||'',t=item(row.dataset.col,row.dataset.item),matches=S.people.get().filter(p=>p.name.toLowerCase().includes(query.toLowerCase())||p.email?.toLowerCase().includes(query.toLowerCase()));const box=popup(anchor,`<div class="popover-title">${fromMention?'Mention a person':'Who is doing this?'}</div>${matches.map(p=>`<button data-pick="${esc(p.id)}" role="option"><img class="avatar" src="${esc(p.avatar)}" alt="">${esc(p.name)} ${t.assignees.includes(p.id)?'✓':''}</button>`).join('')}<button data-new-person>+ Add ${query?esc(query):'a person'}…</button>`,{mentions:fromMention});$$('[data-pick]',box).forEach(b=>b.onclick=()=>{if(fromMention&&editEl()){editEl().textContent=editEl().textContent.replace(/@[^@\n]*$/,'').trimEnd();finishEdit()}change(()=>{const current=item(row.dataset.col,row.dataset.item);setAssignee(current,S.people.get().find(p=>p.id===b.dataset.pick),{remove:current.assignees.includes(b.dataset.pick)&&!fromMention,resolveHint})});closePop()});$('[data-new-person]',box).onclick=()=>{if(fromMention&&editEl()){editEl().textContent=editEl().textContent.replace(/@[^@\n]*$/,'').trimEnd();finishEdit()}closePop();createPerson(query,row.dataset.col,row.dataset.item,resolveHint)};if(fromMention){const previousKeys=anchor.onkeydown;box.restoreKeys=()=>{if(editEl()===anchor)anchor.onkeydown=previousKeys};S.mentionIndex.set(0);const opts=$$('[data-pick]',box);opts[0]?.classList.add('active');anchor.onkeydown=e=>{if(['ArrowDown','ArrowUp','Enter','Escape'].includes(e.key)){e.preventDefault();if(e.key==='Escape'){closePop();return}if(e.key==='Enter'){opts[S.mentionIndex.peek()]?.click();return}opts[S.mentionIndex.peek()]?.classList.remove('active');const index=Math.max(0,Math.min(opts.length-1,S.mentionIndex.peek()+(e.key==='ArrowDown'?1:-1)));S.mentionIndex.set(index);opts[index]?.classList.add('active')}}}}
function suggest(el){const row=el.closest('[data-item]'),text=el.innerText,m=/@([^@\n]*)$/.exec(text);if(m)return peoplePicker(row,el,m[1],true);closePop();if(text.trim().length<12)return suggestTask.cancel();suggestTask.run({data:{query:text,duplicate:true,boardId:S.boardId.get(),columnId:row.dataset.col,exclude:S.boardId.get()+':'+row.dataset.item}}).then(outcome=>{const r=S.suggestions.peek();if(outcome!=='committed'||!editEl()||!r.hits.length)return;const box=popup(el,`<div class="popover-title">${r.mode==='hybrid'?'Similar thoughts already exist':'Possible text duplicate'}</div>${r.hits.map((h,i)=>`<button data-hit="${i}" role="option">${esc(h.title)}<small>${esc(h.boardTitle)} / ${esc(h.columnTitle)}</small></button>`).join('')}<button data-dismiss>Keep this as a separate item</button>`);$$('[data-hit]',box).forEach(b=>b.onclick=()=>{const h=r.hits[Number(b.dataset.hit)];finishEdit();focusItem(h.boardId,h.itemId)});$('[data-dismiss]',box).onclick=()=>closePop()}).catch(()=>{})}
function itemMenu(row,anchor){finishEdit();const col=row.dataset.col,id=row.dataset.item,t=item(col,id),box=popup(anchor,`<button data-a="select">${S.selected.has(id)?'Deselect':'Select for sharing'}</button><button data-a="share">Share this item</button><button data-a="up">Move up ↑</button><button data-a="down">Move down ↓</button><button data-a="move">Move to another column…</button><button data-a="remove" class="danger">Remove item…</button>`);box.onclick=e=>{const a=e.target.closest('[data-a]')?.dataset.a;if(!a)return;closePop();if(a==='select'){S.selected.toggle(id);return renderBoard()}if(a==='share'){S.selected.only(id);return shareDialog('item')}if(a==='remove'){if(confirm('Remove this item? Undo is available from More.'))change(()=>{const c=board().columns.find(c=>c.id===col);c.items=c.items.filter(t=>t.id!==id)});return}if(a==='move'){dialog('Move this thought',`<div class="stack">${board().columns.filter(c=>c.id!==col).map(c=>`<button class="button" data-move="${esc(c.id)}">${esc(c.title)}</button>`).join('')}</div>`);$$('[data-move]').forEach(b=>b.onclick=()=>{change(cmd('moveItem',{...ref(col,id),toColumnId:b.dataset.move}));closeDialog()});return}change(cmd('moveItem',{...ref(col,id),delta:a==='up'?-1:1}))}}
function columnMenu(id,anchor){const box=popup(anchor,'<button data-a="share">Share this column</button><button data-a="left">Move left ↑</button><button data-a="right">Move right ↓</button><button data-a="remove" class="danger">Remove column…</button>');box.onclick=e=>{const a=e.target.closest('[data-a]')?.dataset.a;if(!a)return;closePop();if(a==='share'){S.columnId.set(id);return shareDialog('column')}if(a==='remove'){if(confirm('Remove this column and its items? Undo is available.'))change(()=>board().columns=board().columns.filter(c=>c.id!==id));return}change(cmd('moveColumn',{boardId:board().id,columnId:id,delta:e.target.dataset.a==='left'?-1:1}))}}
function dialog(title,html,{wide=false,dismiss=true}={}){finishEdit();closeDialog();closePop();const opener=document.activeElement;if(opener)S.modalReturn.set(opener);overlays.innerHTML=`<div class="backdrop"><section class="dialog${wide?' wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">${dismiss?'<button class="close" aria-label="Close">'+icon('close')+'</button>':''}<h2 id="dialog-title">${esc(title)}</h2>${html}</section></div>`;$('.close',overlays)?.addEventListener('click',()=>closeDialog());$('.backdrop',overlays).onclick=e=>{if(dismiss&&e.target.classList.contains('backdrop'))closeDialog()};const first=$('input,textarea,button:not(.close),a',overlays);first?.focus();S.dialog.set({open:true,dismiss});app.inert=true;}
/** Mirrors a dialog form's text fields into the dialogDraft owner. The inputs stay the live surface, so IME composition is untouched. */
function trackDraft(selector){const form=$(selector);S.draft.open(form.id,Object.fromEntries([...new FormData(form)].filter(([,v])=>typeof v==='string')));form.addEventListener('input',e=>{const t=e.target;if(t.name&&t.type!=='file')S.draft.set(t.name,t.value)})}
function closeDialog(){S.dialogEpoch.bump();searchTask.cancel();S.batch(()=>{S.draft.clear();S.photoImage.set(null);S.photoReview.set(null)});S.photoForm.clear();app.inert=false;overlays.innerHTML='';S.dialog.set({open:false,dismiss:true});S.modalReturn.take()?.focus?.()}
function boardURL(boardId,itemId){const params=new URLSearchParams({board:boardId,stateBackend:documentBackend});if(itemId)params.set('item',itemId);return '/?'+params}
function focusItem(boardId,itemId){finishEdit();S.batch(()=>{S.boardId.set(boardId);S.selected.clear()});closeDialog();renderBoard();if(!shared())history.replaceState({},'',boardURL(boardId,itemId));requestAnimationFrame(()=>{const el=$('#item-'+CSS.escape(itemId));el?.scrollIntoView({behavior:'smooth',block:'center'});el?.classList.add('focused')})}
function pages(){dialog('Choose a page',`<div class="stack">${ws().boards.map(b=>`<button class="dialog-item" data-board="${esc(b.id)}">${icon('boards')}<span class="item-main">${esc(b.title)}<small>${b.columns.length} columns · ${b.columns.reduce((n,c)=>n+c.items.length,0)} thoughts</small></span>${b.id===S.boardId.get()?'✓':''}</button>`).join('')}</div><div class="separated"><p class="small muted">On this page</p>${board().columns.map(c=>`<button data-jump="${esc(c.id)}">${esc(c.title)} ↗</button>`).join('')}</div>${!shared()?'<div class="actions"><button class="button" id="new-board">+ New page</button><button class="button" id="new-column">+ Column</button><button id="photo-import">'+icon('camera')+' From a photo</button></div>':''}`);$$('[data-board]',overlays).forEach(el=>el.onclick=()=>{S.batch(()=>{S.boardId.set(el.dataset.board);S.selected.clear()});closeDialog();renderBoard();if(!shared())history.replaceState({},'',boardURL(S.boardId.get()));void autoArt()});$$('[data-jump]',overlays).forEach(el=>el.onclick=()=>{closeDialog();$('#column-'+CSS.escape(el.dataset.jump))?.scrollIntoView({behavior:'smooth',block:'start'})});$('#new-board')?.addEventListener('click',()=>nameDialog('A fresh page','Page title',title=>{const b=newBoard(title);try{change(()=>{ws().boards.push(b)},{afterChange:()=>S.boardId.set(b.id)})}finally{if(ws()?.boards.some(page=>page.id===b.id))closeDialog()}}));$('#new-column')?.addEventListener('click',()=>nameDialog('A new column','Column title',title=>{const c={id:uid(),title,subtitle:'A little progress, every day.',note:'Make it\nhappen.',icon:'auto',items:[]};change(()=>board().columns.push(c));closeDialog();void redraw(c.id)}));$('#photo-import')?.addEventListener('click',photoDialog)}
function nameDialog(title,label,fn){dialog(title,`<form id="name-form"><label>${esc(label)}<input name="name" required maxlength="120" autocomplete="off"></label><button class="primary">Create</button></form>`);trackDraft('#name-form');$('#name-form').onsubmit=e=>{e.preventDefault();fn(new FormData(e.target).get('name').trim())}}
function searchDialog(){dialog('Find a thought',`<input class="palette-input" id="search-query" type="search" placeholder="Words, meaning, a ticket…" aria-label="Search workspace" autocomplete="off"><p class="small muted" id="search-mode">Your current page and column come first when relevance is similar.</p><div class="search-hits" role="listbox" id="hits"></div><p class="small muted">↑ ↓ to explore · Enter to open · Esc to close</p>`);S.batch(()=>{S.searchResults.set(null);S.searchActive.set(0)});const hitList=()=>S.searchResults.peek()?.hits||[];const input=$('#search-query'),container=$('#hits');input.oninput=()=>{searchTask.run({read:()=>({query:input.value,boardId:S.boardId.get(),columnId:S.columnId.get()})}).then(outcome=>{if(outcome!=='committed'||!container.isConnected)return;const r=S.searchResults.peek(),hits=r.hits;S.searchActive.set(0);$('#search-mode').textContent=r.mode==='hybrid'?'Words + meaning · current page and column prioritized':r.warning||'Word search · current page and column prioritized';container.innerHTML=hits.map((h,i)=>`<button class="search-hit${!i?' active':''}" data-result="${i}" role="option"><small>${esc(h.boardTitle)} / ${esc(h.columnTitle)}</small><span class="text">${esc(h.title)}</span></button>`).join('')||'<p class="muted small">No matching thoughts yet.</p>';$$('[data-result]',container).forEach(b=>b.onclick=()=>{const h=hitList()[Number(b.dataset.result)];focusItem(h.boardId,h.itemId)})}).catch(e=>{if(container.isConnected)$('#search-mode').textContent=e.message})};input.onkeydown=e=>{if(!['ArrowDown','ArrowUp','Enter'].includes(e.key))return;e.preventDefault();if(e.key==='Enter'){const h=hitList()[S.searchActive.peek()];if(h)focusItem(h.boardId,h.itemId);return}const active=Math.max(0,Math.min(hitList().length-1,S.searchActive.peek()+(e.key==='ArrowDown'?1:-1)));S.searchActive.set(active);$$('.search-hit',container).forEach((b,i)=>b.classList.toggle('active',i===active));$('.search-hit.active',container)?.scrollIntoView({block:'nearest'})}}
function profileHover(anchor){if(S.hoverCard.get())return;const p=S.people.get().find(p=>p.id===anchor.dataset.person);if(!p)return;hoverCard(anchor,`<strong>${esc(p.name)}</strong><small>${tasksForPerson(ws(),p.id).filter(t=>!t.item.done).length} open thoughts${p.avatarPending?' · your photo proposal':''}</small><small>Click to see their pages</small>`)}
function hoverCard(anchor,html){clearHover();const card=document.createElement('div');card.className='hover-card';card.innerHTML=html;document.body.append(card);const r=anchor.getBoundingClientRect();card.style.left=Math.max(12,Math.min(innerWidth-card.offsetWidth-12,r.right-100))+'px';card.style.top=Math.max(12,Math.min(innerHeight-card.offsetHeight-100,r.bottom+10))+'px';S.hoverCard.set(card,c=>c.remove())}
function clearHover(){S.hoverEpoch.bump();S.hoverCard.clear()}
const getTicket=ref=>S.loadTicket(ref,()=>post('ticket',{reference:ref,repo:board().githubRepo}));
async function ticketHover(anchor){if(shared())return;S.hoverEpoch.bump();const alive=S.hoverEpoch.guard();try{const t=await getTicket(anchor.dataset.ticket);if(!alive()||!anchor.matches(':hover'))return;hoverCard(anchor,`<strong>${esc(t.title)}</strong><small>${esc(t.label)} · ${esc(t.kind)} · ${esc(t.state)}</small>`)}catch{}}
async function ticketDialog(ref,row){dialog('Opening ticket…','<p class="muted">Checking the source.</p>');const alive=S.dialogEpoch.guard();try{const t=await getTicket(ref);if(!alive())return;dialog(t.title,`<p class="eyebrow">${esc(t.label)} · ${esc(t.kind)} · ${esc(t.state)}</p><p class="small">${esc(t.description||'No description.')}</p><div class="actions"><a class="button" href="${esc(safeURL(t.url))}" target="_blank" rel="noopener noreferrer">Open in ${esc(t.provider)} ↗</a>${row&&!shared()?'<button id="backlink" class="button">Add a board link to the ticket</button>':''}</div>`);$('#backlink')?.addEventListener('click',async()=>{if(!confirm('Post a comment on this ticket linking to this board item? The board still requires sign-in.'))return;try{await flush();const r=await post('backlink',{reference:ref,repo:board().githubRepo,boardId:S.boardId.get(),itemId:row.dataset.item});toast(r.status==='sent'?'Comment posted.':'Delivery is pending.')}catch(e){toast(e.message)}})}catch(e){if(!alive())return;dialog('Ticket unavailable',`<p>${esc(e.message)}</p><p class="small muted">The reference remains in your task. Connect the integration to enable its preview.</p>`)}}
async function profile(id){clearHover();const p=S.people.get().find(p=>p.id===id)||{id,name:S.user.get()?.name||'Your profile',avatar:'/placeholder.svg',isSelf:id===S.user.get()?.id,accounts:[]},tasks=tasksForPerson(ws(),id);dialog(p.name,`<div class="profile-title"><img class="profile-photo" src="${esc(p.avatar||'/placeholder.svg')}" alt="${esc(p.name)}"><p class="small muted">${tasks.filter(t=>!t.item.done).length} open thoughts across ${new Set(tasks.map(t=>t.boardId)).size} pages</p>${p.avatarPending?'<p class="small">Your proposed photo is awaiting their confirmation.</p>':''}</div>${!shared()?`<div class="actions"><label class="button">${icon('camera')} ${p.isSelf?'Change photo':'Suggest a photo'}<input type="file" id="avatar-upload" accept="image/png,image/jpeg,image/webp" class="sr-only"></label></div><p class="small muted">${p.isSelf?'Your own photo changes immediately.':'Suggestions are only accepted when no profile photo is available. You see yours immediately; everyone else sees it after the owner approves.'}</p><div class="separated"><p class="small muted">Connected accounts</p>${(p.accounts||[]).map(a=>a.url?`<a class="button" href="${esc(safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${esc(a.provider)} ↗</a>`:`<span class="pill">${esc(a.provider)}</span>`).join('')}${p.slackUrl?`<a class="button" href="${esc(safeURL(p.slackUrl))}" target="_blank" rel="noopener noreferrer">Slack ↗</a>`:''}<div class="actions">${(S.config.get()?.providers||[]).map(provider=>`<button data-link-provider="${provider}" class="button">${p.isSelf?'Link':'Suggest linking'} ${provider}</button>`).join('')||'<p class="small muted">No OAuth providers are configured yet.</p>'}</div></div>`:''}<div class="separated stack">${tasks.map((t,i)=>`<button class="dialog-item" data-task-index="${i}"><span>${t.item.done?'✓':'○'}</span><span class="item-main">${esc(t.item.text)}<small>${esc(t.boardTitle)} / ${esc(t.columnTitle)}</small></span></button>`).join('')||'<p class="muted">No assigned thoughts yet.</p>'}</div>`);$$('[data-task-index]').forEach(b=>b.onclick=()=>{const t=tasks[Number(b.dataset.taskIndex)];focusItem(t.boardId,t.item.id)});$('#avatar-upload')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const image=await fileImage(file,{avatar:true});await flush();const r=await post('avatar',{target:id,image});await refreshPeople();profile(id);toast(r.status==='pending'?'Photo proposed. Only you and the owner see it until confirmation.':'Your photo is updated.')}catch(e){toast(e.message)}});$$('[data-link-provider]').forEach(b=>b.onclick=async()=>{if(p.isSelf)return oauth(b.dataset.linkProvider,true);try{await post('proposals/link',{target:id,provider:b.dataset.linkProvider});toast('Request added. They must sign in and confirm ownership of that account.')}catch(e){toast(e.message)}})}
async function refreshPeople(){const p=await api('people');S.batch(()=>{S.people.set(p.people);S.requests.set(p.requests)});renderBoard()}
async function fileImage(file,{avatar=false}={}){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12000000)throw Error('Choose a PNG, JPEG or WebP under 12 MB.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');if(avatar){canvas.width=256;canvas.height=256;const size=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,256,256)}else{const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height)}bitmap.close();const result=canvas.toDataURL('image/jpeg',.8);if(result.length>(avatar?290000:1800000))throw Error('The compressed image is still too large. Please use a smaller image.');return result}
function createPerson(name='',col='',taskId='',resolveHint=''){dialog('Someone new',`<form id="person-form"><label>Name<input name="name" value="${esc(name)}" required maxlength="120" autocomplete="off"></label><label>Email<input name="email" type="email" required autocomplete="off"></label><label>Photo, optional<input name="avatar" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="small muted">This creates an invited person, not an account impersonating them. They sign in to confirm their identity and suggested photo.</p><button class="primary">Add person</button></form>`);trackDraft('#person-form');$('#person-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=$('button',e.target);b.disabled=true;try{await flush();const p=(await post('people',{name:f.get('name'),email:f.get('email')})).person;const photo=f.get('avatar');if(photo?.size)await post('avatar',{target:p.id,image:await fileImage(photo,{avatar:true})});await loadWorkspace();const t=item(col,taskId);if(t)change(()=>setAssignee(item(col,taskId),p,{resolveHint}));closeDialog();toast('Person added.')}catch(e){toast(e.message);b.disabled=false}}}
function moreDialog(){dialog('In the margins',`<div class="stack"><button class="dialog-item" id="my-profile">${icon('person')} Your profile & accounts</button><button class="dialog-item" id="requests">${icon('check')} Confirmations <span class="pill">${S.requests.get().filter(p=>p.target===S.user.get()?.id).length}</span></button><button class="dialog-item" id="workspace-settings">${icon('boards')} Page & workspace settings</button><button class="dialog-item" id="connections">${icon('more')} Connections & cloud</button></div><div class="actions separated"><button class="button" id="undo"${S.documentStore.canUndo?'':' disabled'}>Undo ↶</button><button class="button" id="redo"${S.documentStore.canRedo?'':' disabled'}>Redo ↷</button><button id="export">Export backup</button><button id="logout">Sign out</button></div>`);$('#my-profile').onclick=()=>profile(S.user.get().id);$('#requests').onclick=requestsDialog;$('#connections').onclick=connections;$('#workspace-settings').onclick=settingsDialog;$('#export').onclick=()=>downloadJSON(ws());$('#undo').onclick=()=>{if(S.documentStore.undo())syncQ().change(ws());closeDialog();renderBoard()};$('#redo').onclick=()=>{if(S.documentStore.redo())syncQ().change(ws());closeDialog();renderBoard()};$('#logout').onclick=async()=>{try{await flush();await post('auth/logout',{});closeDialog();resetPrivateState();await start()}catch(e){toast(e.message)}}}
function settingsDialog(){dialog('A few page details',`<form id="settings-form"><label>Workspace name<input name="space" maxlength="120" value="${esc(ws().name)}" required></label><label>Default GitHub repository for #123 references<input name="repo" placeholder="owner/repository" value="${esc(board().githubRepo||'')}" pattern="[\\w.-]+/[\\w.-]+"></label><label>Footer note<textarea name="footer" maxlength="240">${esc(board().footer)}</textarea></label><button class="primary">Save details</button></form>`);trackDraft('#settings-form');$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);change(()=>{ws().name=f.get('space');board().githubRepo=f.get('repo');board().footer=f.get('footer')});closeDialog()}}
function connections(){const c=S.config.get();dialog('Behind the paper',`<p class="notice">${c.test?'Explicit local test database — not cloud.':'Connected to the configured cloud database.'}</p><div class="stack small"><p>Login: ${esc(c.providers.join(', ')||'email only')}</p><p>Email: ${c.email?'Resend configured':'not configured'}</p><p>Semantic search: ${c.ai.embedding?'provider configured':'word search only — connect embeddings'}</p><p>AI drawings: ${c.ai.image?'Cloudflare configured; daily application cap applies':'local illustrations only — connect Cloudflare'}</p><p>Photo import: ${c.ai.vision?'vision provider configured':'not configured'}</p><p>GitHub / Slack / Linear tokens: ${Object.entries(c.integrations).filter(([,v])=>v).map(([k])=>esc(k)).join(', ')||'none'}</p></div><p class="small muted">Configured does not guarantee provider access or remaining quota. Provider errors are shown when a feature runs. Set credentials on the server with <code>npm run setup</code>; nothing secret is stored in this page.</p>${S.user.get().owner?'<button class="button" id="sync-slack">Import Slack people</button>':''}`);$('#sync-slack')?.addEventListener('click',async()=>{try{await flush();const r=await post('slack/sync',{});await loadWorkspace();closeDialog();toast(`${r.count} Slack profiles checked. Login identities are not automatically merged.`)}catch(e){toast(e.message)}})}
function requestsDialog(){const list=S.requests.get().filter(p=>p.target===S.user.get().id);dialog('Your confirmations',`${list.map(p=>`<section class="pending-card"><p>${esc(S.people.get().find(x=>x.id===p.by)?.name||'A teammate')} ${p.type==='avatar'?'suggested this photo.':`suggested linking ${esc(p.provider)}.`}</p>${p.type==='avatar'?`<img src="/api/asset?id=${esc(p.asset)}" class="profile-photo" alt="Proposed photo"><div class="actions"><button class="button" data-confirm="${esc(p.id)}">Approve photo</button><button data-reject="${esc(p.id)}">Reject</button></div>`:`<button class="button" data-prove="${esc(p.id)}">Sign in to ${esc(p.provider)} to confirm</button><button data-reject="${esc(p.id)}">Reject</button>`}</section>`).join('')||'<p class="muted">Nothing awaiting your confirmation.</p>'}<p class="small muted">Linking proves control of the other account. No teammate can link an account on your behalf.</p>`);$$('[data-confirm],[data-reject]').forEach(b=>b.onclick=async()=>{try{await post('proposals/confirm',{id:b.dataset.confirm||b.dataset.reject,accept:!!b.dataset.confirm});await refreshPeople();requestsDialog()}catch(e){toast(e.message)}});$$('[data-prove]').forEach(b=>b.onclick=()=>{const p=list.find(p=>p.id===b.dataset.prove);oauth(p.provider,true,p.id)})}
function shareDialog(kind){const count=S.selected.size;kind||=count===1?'item':count>1?'items':'board';dialog('Send a little progress',`<label>What should the link show?<select id="share-kind"><option value="board">This page</option><option value="column">Current column</option><option value="item" ${count!==1?'disabled':''}>Selected thought</option><option value="items" ${!count?'disabled':''}>Selected thoughts (${count})</option><option value="space">All pages in the workspace</option></select></label><div class="share-options"><label><input id="share-neighbors" type="checkbox"> Include faded neighboring items</label></div><p class="small muted">Anyone with this read-only link can see the selected content. Private email and account details are excluded. The preview uses the latest saved state, not AI.</p><button class="primary" id="make-share">Create view link</button><div id="share-result"></div>`,{wide:true});$('#share-kind').value=kind;$('#make-share').onclick=async()=>{const button=$('#make-share');button.disabled=true;try{await flush();const kind=$('#share-kind').value,scope={kind,boardId:S.boardId.get(),columnId:S.columnId.get()||board().columns[0]?.id,itemIds:[...S.selected.get()],neighbors:$('#share-neighbors').checked},r=await post('share',scope);$('#share-result').innerHTML=`<img class="preview" src="${esc(r.preview)}" alt="Generated link preview"><label>Read-only link<input id="share-url" readonly value="${esc(r.url)}"></label><div class="actions"><button class="button" id="copy-link">Copy link</button><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a><button class="danger" id="revoke-link">Revoke</button></div><p class="small muted">Messengers can cache previews. Revoking a link cannot remove a screenshot they already cached.</p>`;$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(r.url);toast('Link copied.')}catch{$('#share-url').select();toast('Select and copy the link.')}};$('#revoke-link').onclick=async()=>{try{await post('share/revoke',{id:r.id});$('#share-result').innerHTML='<p>Link revoked.</p>'}catch(e){toast(e.message)}}}catch(e){toast(e.message)}finally{button.disabled=false}}}
async function autoArt(){if(shared()||!S.config.get()?.ai?.image&&!S.config.get()?.ai?.embedding)return;for(const c of board().columns)if(!c.illustrationId&&!S.artAttempts.has(c.id+':'+c.title)){S.artAttempts.add(c.id+':'+c.title);await redraw(c.id,false)}}
async function redraw(id,force=false){if(shared()||!S.config.get()?.ai?.image&&!S.config.get()?.ai?.embedding){if(force)toast('Connect an image provider in server settings. Local drawings remain available.');return}const b=board(),c=b.columns.find(c=>c.id===id);if(!c)return;const title=c.title,alive=S.workspaceEpoch.guard(),boardId=b.id;try{const r=await post('illustration',{title,description:c.subtitle,force});const current=ws()?.boards.find(x=>x.id===boardId)?.columns.find(x=>x.id===id);if(!alive()||!current||current.title!==title)return;change(cmd('setField',{target:'column',boardId,columnId:id,key:'illustrationId',value:r.id}),{render:!editEl(),background:true});if(r.warning&&force)toast(r.warning)}catch(e){if(force)toast(e.message)}}
function photoDialog(){
 dialog('From paper to a page',`<p>Photograph your notebook, review the transcription, then add it as a new page. Nothing is created until you confirm.</p><p class="small muted">The photo is sent to your configured vision provider. Avoid uploading private information you cannot share with that provider.</p><label>Photo<input type="file" id="photo-file" accept="image/png,image/jpeg,image/webp"></label><div id="photo-result"></div><div class="actions"><button class="primary" id="read-photo"${S.config.get().ai.vision?'':' disabled'}>Read this photo</button></div>${!S.config.get().ai.vision?'<p class="notice">Connect VISION_BASE_URL, VISION_MODEL and VISION_API_KEY on the server first.</p>':''}`,{wide:true});
 S.batch(()=>{S.photoImage.set(null);S.photoReview.set(null)});
 const input=$('#photo-file'),result=$('#photo-result'),button=$('#read-photo');
 input.onchange=async event=>{S.photoEpoch.bump();const alive=S.photoEpoch.guard();try{const data=await fileImage(event.target.files[0]);if(!result.isConnected||!alive())return;S.photoImage.set(data);result.replaceChildren();const preview=document.createElement('img');preview.className='preview-photo';preview.src=data;preview.alt='Your photo';result.append(preview)}catch(error){if(result.isConnected)toast(error.message)}};
 button.onclick=async()=>{
  const image=S.photoImage.peek();if(!image)return toast('Choose a photo first.');
  const alive=S.photoEpoch.guard();button.disabled=true;input.disabled=true;button.textContent='Reading the page…';
  try{
   const draft=await post('photo',{image});if(!result.isConnected||!alive())return;
   const form=reviewPhoto(result,draft,{session:createPhotoReviewSession(S.photoReview),onError:error=>toast(error.message),onConfirm:async value=>{
    await flush();const response=await post('import',{board:value});S.boardId.set(response.boardId);await loadWorkspace();if(result.isConnected)closeDialog();toast('A new page was added from your reviewed draft.');
   }});
   S.photoForm.set(form,f=>{f.onsubmit=null});
  }catch(error){if(result.isConnected)toast(error.message)}finally{if(button.isConnected){button.disabled=false;input.disabled=false;button.textContent='Read this photo'}}
 };
}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&ws()&&!shared()){e.preventDefault();return searchDialog()}if(e.key==='Escape'){closePop();if(S.dialog.get().open&&S.dialog.get().dismiss)closeDialog();clearHover()}if(e.key==='Tab'&&S.dialog.get().open){const controls=$$('button:not(:disabled),a[href],input:not(:disabled),textarea,select',[...overlays.children][0]).filter(el=>el.offsetParent!==null);if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});document.addEventListener('pointerdown',e=>{if(popEl()&&!popEl().contains(e.target)&&!e.target.closest('[data-edit],[data-assign],[data-item-menu],[data-column-menu]'))closePop()});window.addEventListener('beforeunload',e=>{if(syncQ()&&syncQ().sequence>syncQ().ack){e.preventDefault();e.returnValue=''}});
await installFont().catch(()=>toast('The custom lettering could not load. A browser fallback is being used.'));await start();
